"""Build an unpublished Jeremiah draft from manually written chapter notes."""
import csv,json,sys
from book_common import ROOT,OUT,source,person,scripture,finish

def load(slug):return json.loads((OUT/(slug+'.json')).read_text(encoding='utf8'))
sources=[dict(next(s for s in load('genesis')['sources'] if s['id']==i)) for i in ['web','atlas-canaan']]
sources[0].update(title='Jeremiah · World English Bible',url='https://ebible.org/engwebp/JER01.htm',summary='The public-domain reading text supplies all 52 chapters.',limits='Chapter order is not a continuous timeline. Speakers’ claims remain attributed. Names shared by different people require separate links.')
sources[0]['limits']+=' Jeremiah 27:1 names Jehoiakim, but 27:3 and 27:12 name Zedekiah. The reading preserves this difference. Jezaniah in 42:1 and Azariah in 43:2 share Hoshaiah as father. Their different names do not establish two separate historical people. Nergal Sharezer occurs twice in 39:3. The group profile does not identify these officials as one person.'
def reviewed(i,title,url,summary,author,year,coverage,scope,limits,publisher,category='Scholarly study',perspective='historical'):
 s=source(i,title,url,summary,category,perspective,limits);s.update(author=author,year=year,publisher=publisher,chapterCoverage=coverage,reviewed=dict(date='2026-10-05',scope=scope));sources.append(s);return s
reviewed('luther-jeremiah-summary','Summary of Jeremiah · Enter the Bible','https://enterthebible.org/courses/jeremiah/lessons/summary-of-jeremiah/','The overview explains warnings, suffering, and hope after Jerusalem’s fall.','Terence E. Fretheim · revised by Michael Chan',2024,list(range(1,53)),'Complete main summary reviewed. Revision marked 08/24. General book context only.','The page’s broad length claim is not used. No verse commentary is attributed to this overview.','Luther Seminary')
reviewed('luther-jeremiah-background','Background of Jeremiah · Enter the Bible','https://enterthebible.org/courses/jeremiah/lessons/background-of-jeremiah/','The background describes Judah’s final kings and the book’s growth.','Terence E. Fretheim · revised by Michael Chan',2024,[1,25,36,39,45,52],'Complete main background reviewed. Revision marked 08/24.','Its proposals about Baruch and later writers are qualified. It dates Jerusalem’s fall to 587 BCE. Other reviewed sources use 586 BCE. Neither date is treated as undisputed. Greek and Hebrew versions differ in length and arrangement.','Luther Seminary')
reviewed('mcclellan-queen','The Queen of Heaven? · Data Over Dogma','https://www.youtube.com/watch?v=rt16_25Irx8','The hosts discuss household offerings and argue for identifying the queen with Astarte.','Dan McClellan · Dan Beecher',None,[7,44],'Original YouTube auto-generated captions reviewed from 12:27 through 19:51. Opening identifies both hosts. The discussion cites Susan Ackerman.','Captions lack reliable speaker labels and may contain errors. Audio and the full episode were not reviewed. No caption wording is quoted. Astarte is the program’s argued identification, not an explicit name in Jeremiah. The cited inscriptions and the full Ackerman book were not independently reviewed.','Data Over Dogma','McClellan commentary')
reviewed('ackerman-record','Gods, Goddesses, and the Women Who Serve Them · publisher record','https://www.eerdmans.com/9780802879561/gods-goddesses-and-the-women-who-serve-them/','Eerdmans verifies the book that Data Over Dogma cites.','Susan Ackerman',2022,[],'Publisher description, contents, author record, and publication details reviewed.','Bibliographic verification only. The full book and its inscriptions were not reviewed. Its claims are not presented as independently examined evidence.','Eerdmans')
reviewed('redditt-record','Introduction to the Prophets · publisher record','https://www.eerdmans.com/9780802828965/introduction-to-the-prophets/','Eerdmans verifies the author, title, ISBN, and date of a book cited by Wikipedia.','Paul L. Redditt',2008,[],'Complete publisher description and publication metadata reviewed. Paperback ISBN 9780802828965 matches the Wikipedia bibliography.','The full book and cited pages 132–33 were not reviewed. This record verifies publication rather than chapter interpretation.','Eerdmans')
w=reviewed('wiki-jeremiah','Book of Jeremiah · Wikipedia','https://en.wikipedia.org/w/index.php?title=Book_of_Jeremiah&oldid=1376288136','The overview describes the book’s sections and different manuscript forms.','Wikipedia contributors',2026,[],'Opening, structure, composition overview, bibliography, revision footer, and license reviewed. Redditt’s cited book checked against Eerdmans.','Overview and bibliography discovery. Reader notes use scripture and reviewed primary material. The bibliography contains a mismatched Kugler and Hartin title that is not adopted here.','Wikipedia','Wikipedia overview');w.update(revisionId=1376288136,revisionUrl=w['url'],license='CC BY-SA 4.0',licenseUrl='https://creativecommons.org/licenses/by-sa/4.0/',citedSourceIds=['redditt-record'])
church='The Church of Jesus Christ of Latter-day Saints'
reviewed('cfm-jeremiah-1','October 19–25. “Before I Formed Thee in the Belly I Knew Thee”: Jeremiah 1–3; 7; 16–18; 20','https://www.churchofjesuschrist.org/study/manual/come-follow-me-for-home-and-church-old-testament-2026/43?lang=eng','The lesson studies Jeremiah’s call, returning to God, temple conduct, and the potter.','The Church of Jesus Christ of Latter-day Saints',2026,[1,2,3,7,16,17,18,20],'Complete main lesson and children’s section reviewed.','Linked talks were not separately reviewed. The lesson’s missionary use of fishers and hunters remains distinct from the pursuit in Jeremiah 16:16–18. Passage-specific questions are original.','The Church of Jesus Christ of Latter-day Saints','Come, Follow Me','lds')
reviewed('cfm-jeremiah-2','October 26–November 1. “I Will Turn Their Mourning into Joy”: Jeremiah 31–33; 36–39; Lamentations 1; 3','https://www.churchofjesuschrist.org/study/manual/come-follow-me-for-home-and-church-old-testament-2026/44?lang=eng','The lesson studies a changed heart, scripture, prophetic counsel, and Ebed-melech’s courage.',church,2026,[31,32,33,36,37,38,39],'Complete main lesson and children’s section reviewed.','Linked talks were not separately reviewed. The Messiah identification is Church teaching. The 2026 assignment does not include Jeremiah 30. Passage-specific questions are original.',church,'Come, Follow Me','lds')
reviewed('lds-jeremiah-helps','Jeremiah 31–33; 36–38; Lamentations 1; 3 · Scripture Helps','https://www.churchofjesuschrist.org/study/manual/scripture-helps-old-testament/42-jeremiah-31-33-36-38-lamentations-1-3?lang=eng','The manual explains Rachel’s grief, the field purchase, Baruch, and Zedekiah’s choices.',church,None,[31,32,33,36,37,38,39],'Jeremiah overview and all Jeremiah Background and Context sections reviewed. Lamentations sections also read for later work.','The manual’s outside references and linked talks were not independently read. Its interpretation of the new covenant and righteous Branch remains in the Church layer. Jeremiah’s death in Egypt is a belief, not an event stated in this book.',church,'LDS Scripture Helps','lds')
rows=list(csv.DictReader((ROOT/'scripts/jeremiah-notes.tsv').open(encoding='utf8'),delimiter='\t'))
