 n=int(row['chapter']);hs=[s['id'] for s in sources if s['perspective']=='historical' and n in s.get('chapterCoverage',[])];ls=[s['id'] for s in sources if s['perspective']=='lds' and n in s.get('chapterCoverage',[])]
 route={29:['jerusalem','babylon'],39:['jerusalem','jericho','riblah','babylon'],40:['ramah','mizpah'],52:['jerusalem','jericho','riblah','babylon']}.get(n,[])
 route_evidence={29:'Jeremiah 29:1–3 describes Elasah and Gemariah delivering the letter from Jerusalem to captives in Babylon. Intermediate roads are not specified.',39:'Jeremiah 39:4–7 traces Zedekiah’s escape, capture near Jericho, judgment at Riblah, and removal to Babylon. Lines connect approximate named locations, not known roads.',40:'Jeremiah 40:1–6 places Jeremiah among captives at Ramah and then with Gedaliah at Mizpah. The exact road and competing site locations remain uncertain.',52:'Jeremiah 52:7–11 repeats Zedekiah’s escape, capture near Jericho, judgment at Riblah, and removal to Babylon. It does not supply the roads.'}.get(n,'Place references do not establish a continuous journey. No travel line is reconstructed.')
 chapters.append(dict(chapter=n,title=row['title'],summary=row['summary'],meaning=row['meaning'],lds=dict(text=row['question'],sourceIds=ls),sourceIds=['web']+hs,people=[p['id'] for p in people if n in p['chapterCoverage']],places=locations[n],eventOrder=n,dateLabel='Chapter order',historicalNote=row['meaning'],mapNote='Map points locate named places. Lines connect stated movements where the passage gives endpoints.',route=route,routeEvidence=route_evidence))
